 const pages=[];let current=[],used=0;for(const item of items){if(item.height>1500)throw Error('ข้อความในหนึ่งแถวยาวเกินหน้ารายงาน กรุณาย่อหมายเหตุ');if(current.length&&used+item.height>1640){pages.push(current);current=[];used=0;}current.push(item);used+=item.height;}pages.push(current);
 if(pages.at(-1).reduce((n,x)=>n+x.height,0)>1370){const tail=[];let h=0;while(pages.at(-1).length&&h+pages.at(-1).at(-1).height<=1370){const item=pages.at(-1).pop();tail.unshift(item);h+=item.height;}pages.push(tail);}
