 ctx.fillStyle='#222';ctx.textAlign='center';ctx.font='bold 27px Tahoma,"Noto Sans Thai"';const titleLines=wrapped(ctx,reportTitle(s,r,year)+' (รายสัปดาห์)',2700);titleLines.forEach((t,i)=>ctx.fillText(t,1461,60+i*33));ctx.font='24px Tahoma,"Noto Sans Thai"';ctx.fillText('ระหว่างวันที่ '+fmt(r.start)+' – '+fmt(r.end),1461,60+titleLines.length*33+10);
