// ==================== 4. MASTER DATA UI ====================
// This module receives UI and persistence callbacks; no separate database state.
export function catalogUI(api){
 const {getState,esc,mutate,modal,field,buttons,selectField}=api;
 const labels={contractors:'ผู้รับจ้าง',supervisors:'ผู้ควบคุมงาน',workTypes:'ประเภทงาน',workNames:'ชื่องาน',years:'ปีงบประมาณ'};
 let tab='contractors',query='';
 const used=(s,key,id)=>key==='contractors'?s.projects.some(p=>p.contractorId===id):key==='supervisors'?s.projects.some(p=>p.supervisorId===id):key==='workNames'?s.projects.some(p=>p.workNameId===id):key==='workTypes'?s.workNames.some(p=>p.typeId===id)||s.projects.some(p=>p.workTypeId===id):false;
 function html(){const s=getState();const rows=(tab==='years'?s.years.map(y=>({id:y,name:String(y)})):s[tab]).filter(x=>x.name.toLowerCase().includes(query.toLowerCase()));return `<div class="card basic-data"><div class="tabs catalog-tabs">${Object.entries(labels).map(([k,v])=>`<button data-catalog-tab="${k}" class="${k===tab?'active':''}">${v}</button>`).join('')}</div><div class="table-top"><div><h2>${labels[tab]}</h2><p class="sub">จัดการรายการพื้นฐาน เลือกใช้ร่วมกันในสัญญา • ข้อมูลรายงานที่ปิดแล้วคงเดิม</p></div><button class="btn primary" data-catalog-add>＋ เพิ่ม${labels[tab]}</button></div><div class="filters"><input id="catalog-search" placeholder="ค้นหา${labels[tab]}" value="${esc(query)}"><span>${rows.length} รายการ</span></div><div class="catalog-list">${rows.map(x=>`<div class="catalog-item"><div><strong>${esc(x.name)}</strong>${tab==='workNames'?`<div class="sub">${esc(s.workTypes.find(t=>t.id===x.typeId)?.name||'ยังไม่ระบุประเภทงาน')}</div>`:''}${x.archived?'<span class="pill warn">เก็บเข้าคลัง</span>':''}</div><div class="actions"><button class="btn" data-catalog-edit="${x.id}">แก้ไข</button>${tab!=='years'?`<button class="btn" data-catalog-archive="${x.id}">${x.archived?'นำกลับมาใช้':'เก็บเข้าคลัง'}</button>`:''}<button class="text-link danger-text" data-catalog-delete="${x.id}">ลบ</button></div></div>`).join('')||'<div class="empty">ยังไม่มีรายการ กดเพิ่มเพื่อเริ่มต้น</div>'}</div></div>`;}
 function edit(id){const s=getState(),key=tab;if(key==='years'){if(!id)return api.addYear();return modal('แก้ไขปีงบประมาณ',`<form>${field('ปี พ.ศ.','year',id,'number','required min="2500" max="2700" step="1"')}${buttons()}</form>`,f=>mutate('แก้ไขปีงบประมาณ',next=>{const old=+id,y=+f.get('year');if(next.projects.some(p=>p.year===old)||next.reports.some(r=>r.year===old))throw Error('ปีนี้มีข้อมูลแล้ว ให้เพิ่มปีใหม่แทนเพื่อคงประวัติ');if(next.years.includes(y)&&y!==old)throw Error('มีปีนี้แล้ว');next.years=next.years.map(n=>n===old?y:n).sort();}));}const x=s[key].find(x=>x.id===id);modal((x?'แก้ไข':'เพิ่ม')+labels[key],`<form>${field('ชื่อ'+labels[key],'name',x?.name||'','text','required maxlength="300"')}${key==='workNames'?selectField('ประเภทงาน (เว้นว่างได้)','typeId',[{value:'',label:'ยังไม่ระบุประเภท'},...s.workTypes.filter(t=>!t.archived).map(t=>({value:t.id,label:t.name}))],x?.typeId||''):''}${buttons()}</form>`,f=>mutate('จัดการ'+labels[key],next=>{const name=f.get('name').trim();if(!name||next[key].some(v=>v.id!==id&&v.name===name))throw Error('ชื่อว่างหรือซ้ำ');let v=next[key].find(v=>v.id===id);if(!v){v={id:key.toUpperCase()+'-'+crypto.randomUUID(),name};next[key].push(v);}v.name=name;if(key==='workNames')v.typeId=f.get('typeId')||'';for(const p of next.projects){if(key==='contractors'&&p.contractorId===id)p.contractor=name;if(key==='supervisors'&&p.supervisorId===id)p.supervisor=name;if(key==='workNames'&&p.workNameId===id){p.title=name;p.workTypeId=v.typeId;}}}));}
 function bind(){document.querySelectorAll('[data-catalog-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.catalogTab;query='';api.render();});document.querySelector('[data-catalog-add]')?.addEventListener('click',()=>edit());document.querySelector('#catalog-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;api.render();const i=document.querySelector('#catalog-search');i.focus();i.setSelectionRange(pos,pos);});document.querySelectorAll('[data-catalog-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.catalogEdit));document.querySelectorAll('[data-catalog-archive]').forEach(b=>b.onclick=async()=>{try{await mutate('จัดการคลัง'+labels[tab],s=>{const x=s[tab].find(x=>x.id===b.dataset.catalogArchive);x.archived=!x.archived;});}catch(e){api.toast(e.message,true);}});document.querySelectorAll('[data-catalog-delete]').forEach(b=>b.onclick=()=>{const key=tab,id=b.dataset.catalogDelete;api.confirmAction('ลบ'+labels[key],'ลบได้เมื่อไม่มีข้อมูลใช้งานอยู่ หากมีการอ้างอิงให้เก็บเข้าคลังแทน',()=>mutate('ลบ'+labels[key],s=>{if(key==='years'){const y=+id;if(s.years.length===1||s.projects.some(p=>p.year===y)||s.reports.some(r=>r.year===y))throw Error('ยังมีข้อมูลอ้างอิงปีนี้ หรือต้องเหลืออย่างน้อยหนึ่งปี');s.years=s.years.filter(x=>x!==y);}else{if(used(s,key,id))throw Error('ยังมีข้อมูลอ้างอิงรายการนี้ กรุณาเก็บเข้าคลังแทน');s[key]=s[key].filter(x=>x.id!==id);}}));});}
 return {html,bind};
}


// ==================== 5. LOCAL STORAGE ====================
let dbPromise;const getDB=()=>dbPromise??=new Promise((resolve,reject)=>{const q=indexedDB.open('pn-weekly',1);q.onupgradeneeded=()=>q.result.createObjectStore('data');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});
export async function readStore(){const db=await getDB();return new Promise((resolve,reject)=>{const q=db.transaction('data').objectStore('data').get('workspace');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
export async function writeStore(state,expectedRevision){const db=await getDB();return new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite'),s=tx.objectStore('data');let conflict=false;const q=s.get('workspace');q.onsuccess=()=>{if(expectedRevision!==undefined&&q.result&&(q.result.revision||0)!==expectedRevision){conflict=true;tx.abort();return;}s.put(state,'workspace');};tx.oncomplete=()=>resolve();tx.onabort=()=>reject(Error(conflict?'ข้อมูลถูกแก้ไขจากอีกแท็บ กรุณารีเฟรชหน้าเว็บก่อนบันทึก':'บันทึกข้อมูลบนอุปกรณ์ไม่สำเร็จ'));tx.onerror=()=>reject(tx.error);});}


// ==================== 6. SUPABASE RPC ====================
export const cloud=(()=>{
const KEY='pn-weekly-cloud';
const config=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'null');}catch{return null;}};
function setConfig(url,key){url=url.trim().replace(/\/$/,'');key=key.trim();if(!/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(url))throw Error('ใช้ URL รูปแบบ https://project.supabase.co');if(!key||key.startsWith('sb_secret_'))throw Error('ใช้ publishable key หรือ anon key');try{const claims=JSON.parse(atob(key.split('.')[1]));if(claims.role==='service_role')throw Error('ใช้ publishable / anon key ไม่ใช่ service-role key');}catch(e){if(e.message.includes('service-role'))throw e;}localStorage.setItem(KEY,JSON.stringify({url,key}));}
async function request(name,body){const c=config();if(!c)throw Error('ยังไม่ได้ตั้งค่า Supabase');const res=await fetch(c.url+'/rest/v1/rpc/'+name,{method:'POST',signal:AbortSignal.timeout(30000),headers:{apikey:c.key,'Content-Type':'application/json'},body:JSON.stringify(body)});let data;try{data=await res.json();}catch{throw Error('Supabase ตอบกลับไม่ถูกต้อง HTTP '+res.status);}if(!res.ok)throw Error(data.message||data.error_description||'เชื่อมต่อฐานข้อมูลไม่สำเร็จ HTTP '+res.status);return data;}
const loadCloud=()=>request('pn2_load_workspace',{});
const saveCloud=(state,revision)=>request('pn2_save_workspace',{payload:state,expected_revision:revision});
function disconnect(){localStorage.removeItem(KEY);}

const amendCloud=(id,patch,revision)=>request('pn2_amend_report',{report_id:id,entries_patch:patch,expected_revision:revision});

return {config,setConfig,loadCloud,saveCloud,amendCloud,disconnect};})();


